test_declarations.form:
it.each([
		grammarError,
		// Observed from the live API: 32 strict tools, then 20 tools with 24 optional fields each.
		"Too many strict tools (32). The maximum number of strict tools supported is 20. Try reducing the number of tools marked as strict.",
		"Schemas contains too many parameters with union types (480 parameters with type arrays or anyOf). This causes exponential compilation cost. Reduce the number of nullable or union-typed parameters (limit: 16 parameters with unions).",
	])

it.each([
		{ name: "OpenAI API keys", apiKey: "sk-proj-test", requestModel: model },
		{
			name: "other OpenAI-compatible endpoints",
			apiKey: "gateway-key",
			requestModel: { ...model, baseUrl: "https://gateway.example.com/v1" },
		},
	])

it.each([
		// Regression for #10965 (provider unknown, no status code in the message).
		"The service is temporarily unavailable. Please retry later.",
		// Bedrock ServiceUnavailableException as formatted by formatBedrockError.
		"Service unavailable: The service is temporarily unavailable.",
	])

it.each([
		// Regression for #10996: node-fetch errors from the google-vertex OAuth token refresh.
		"request to https://oauth2.googleapis.com/token failed, reason:",
		"request to https://oauth2.googleapis.com/token failed, reason: connect ECONNREFUSED 127.0.0.1:9",
	])

it.each([
		// Regression for #11057: status codes inside ids or other numbers are not status codes.
		'401 {"type":"error","error":{"type":"authentication_error","message":"invalid x-api-key"},"request_id":"req_011CU503xyz"}',
		"400 image exceeds 5 MB maximum: 5316784 bytes > 5242880 bytes",
	])

it.each([
		["OpenRouter behind a proxy", { provider: "openrouter", baseUrl: "https://proxy.example.com/v1" }],
		["a regional OpenRouter endpoint", { provider: "custom", baseUrl: "https://us.openrouter.ai/api/v1" }],
		[
			"a proxy declared through compat",
			{
				provider: "custom",
				baseUrl: "https://proxy.example.com/v1",
				compat: { imageInput: "state-image-urls" as const, sendImageOptInHeader: false },
			},
		],
	])
